import path from "node:path";
import { drizzle } from "drizzle-orm/node-postgres";
import { migrate } from "drizzle-orm/node-postgres/migrator";
import type pg from "pg";

/** Folder with SQL migrations generated by drizzle-kit (copied next to dist/ in the Docker image). */
export function migrationsFolder(): string {
  return process.env.MIGRATIONS_DIR ?? path.resolve(process.cwd(), "drizzle");
}

export async function runMigrations(pool: pg.Pool, folder = migrationsFolder()): Promise<void> {
  await migrate(drizzle(pool), { migrationsFolder: folder });
}
